public class CommandLineTest {

    private CommandLine commandLine;
    private Option optionA;
    private Option optionB;
    private Option optionWithArg;
    private Option optionWithMultipleArgs;

    @Before
    public void setUp() throws Exception {
        commandLine = CommandLine.builder().get();

        optionA = Option.builder("a").build();
        optionB = Option.builder("b").build();
        optionWithArg = Option.builder("f").hasArg(true).build();
        optionWithMultipleArgs = Option.builder("m").hasArgs().build();
    }

    @Test
    public void testEmptyCommandLine() {
        assertTrue(commandLine.getArgList().isEmpty());
        assertArrayEquals(new String[0], commandLine.getArgs());
        assertArrayEquals(new Option[0], commandLine.getOptions());
        assertFalse(commandLine.hasOption("a"));
    }

    @Test
    public void testAddArg() {
        commandLine = CommandLine.builder()
                .addArg("arg1")
                .addArg("arg2")
                .addArg(null)
                .get();

        final List<String> argList = commandLine.getArgList();
        assertEquals(2, argList.size());
        assertEquals("arg1", argList.get(0));
        assertEquals("arg2", argList.get(1));

        final String[] args = commandLine.getArgs();
        assertEquals(2, args.length);
        assertEquals("arg1", args[0]);
        assertEquals("arg2", args[1]);
    }

    @Test
    public void testAddOption() {
        commandLine = CommandLine.builder()
                .addOption(optionA)
                .addOption(optionB)
                .addOption(null)
                .get();

        final Option[] options = commandLine.getOptions();
        assertEquals(2, options.length);
    }

    @Test
    public void testHasOptionWithString() {
        commandLine = CommandLine.builder()
                .addOption(optionA)
                .get();

        assertTrue(commandLine.hasOption("a"));
        assertFalse(commandLine.hasOption("b"));
        assertFalse(commandLine.hasOption("nonexistent"));
    }

    @Test
    public void testHasOptionWithChar() {
        commandLine = CommandLine.builder()
                .addOption(optionA)
                .get();

        assertTrue(commandLine.hasOption('a'));
        assertFalse(commandLine.hasOption('b'));
    }

    @Test
    public void testHasOptionWithOption() {
        commandLine = CommandLine.builder()
                .addOption(optionA)
                .get();

        assertTrue(commandLine.hasOption(optionA));
        assertFalse(commandLine.hasOption(optionB));
    }

    @Test
    public void testHasOptionWithOptionGroup() {
        final OptionGroup group = new OptionGroup();
        group.addOption(optionA);
        group.setSelected(optionA);

        commandLine = CommandLine.builder()
                .addOption(optionA)
                .get();

        assertTrue(commandLine.hasOption(group));

        final OptionGroup emptyGroup = new OptionGroup();
        assertFalse(commandLine.hasOption(emptyGroup));

