    @Test
    public void testAppendOptionGroupSorting() {
        Options options = new Options();
        OptionGroup group = new OptionGroup();
        group.addOption(Option.builder("z").desc("Z").build());
        group.addOption(Option.builder("m").desc("M").build());
        group.addOption(Option.builder("a").desc("A").build());
        options.addOptionGroup(group);

        formatter.setOptionComparator(null);

        StringWriter sw = new StringWriter();
        PrintWriter pw = new PrintWriter(sw);
        formatter.printUsage(pw, 80, "app", options);
        pw.flush();

        String output = sw.toString();
