    public void testMultipleOptionsWithSameLongNameDifferentShort() {
        Option opt1 = Option.builder("a").longOpt("same").build();
        Option opt2 = Option.builder("b").longOpt("same").build();

        options.addOption(opt1);
        options.addOption(opt2);

